const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const start = '2016-01-01';
    const end = '2017-01-01';
    const scale = 1000; // per instructions, >=1000m
    const aswan = ee.Geometry.Point([32.8772, 23.9685]).buffer(15000);
    const gerd = ee.Geometry.Point([35.093, 11.213]).buffer(15000);

    // 2. Data Acquisition & Check with fallback
    let datasetId = 'NOAA/VIIRS/DNB/MONTHLY_V1/VCMSLCFG';
    let col = ee.ImageCollection(datasetId).filterDate(start, end);
    let size = await col.size().getInfo();

    if (size === 0) {
      // Fallback #1: alternate product
      const fallbackId = 'NOAA/VIIRS/DNB/MONTHLY_V1/VCMCFG';
      let colFallback = ee.ImageCollection(fallbackId).filterDate(start, end);
      let sizeFallback = await colFallback.size().getInfo();
      if (sizeFallback > 0) {
        datasetId = fallbackId;
        col = colFallback;
        size = sizeFallback;
      } else {
        // Fallback #2: widen date window
        const start2 = '2015-12-01';
        const end2 = '2017-02-01';
        let colWiden = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMSLCFG').filterDate(start2, end2);
        let sizeWiden = await colWiden.size().getInfo();
        if (sizeWiden > 0) {
          datasetId = 'NOAA/VIIRS/DNB/MONTHLY_V1/VCMSLCFG';
          col = colWiden.filterDate(start, end); // still restrict to 2016 for analysis
          size = await col.size().getInfo();
        } else {
          let colWiden2 = ee.ImageCollection(fallbackId).filterDate(start2, end2);
          let sizeWiden2 = await colWiden2.size().getInfo();
          if (sizeWiden2 > 0) {
            datasetId = fallbackId;
            col = colWiden2.filterDate(start, end);
            size = await col.size().getInfo();
          } else {
            console.log('2016 Images: 0 (both datasets, even after widening)');
            console.log('C1');
            return;
          }
        }
      }
    }
    console.log(`Dataset: ${datasetId}, 2016 Images: ${size}`);

    // 3. Processing - annual composite of avg_rad with coverage mask
    const avgRadColl = col.select('avg_rad');
    const yearImg = avgRadColl.median();
    // Mask where any month had cloud-free coverage
    const cfSum = col.select('cf_cvg').sum();
    const yearMasked = yearImg.updateMask(cfSum.gt(0));

    async function regionStats(region, label) {
      const validCount = await yearMasked.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: region,
        scale: scale,
        maxPixels: 1e9
      }).get('avg_rad').getInfo();

      const totalCount = await ee.Image(1).rename('ones').reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: region,
        scale: scale,
        maxPixels: 1e9
      }).get('ones').getInfo();

      if (!totalCount || totalCount === 0) {
        console.log(`${label} Pixels: total=0`);
        return {ok: false, reason: 'C2'};
      }

      if (!validCount || validCount === 0) {
        console.log(`${label} Pixels: valid=0/${totalCount} (0.0%)`);
        return {ok: false, reason: 'C2'};
      }

      const meanVal = await yearMasked.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: region,
        scale: scale,
        maxPixels: 1e9
      }).get('avg_rad').getInfo();

      if (meanVal === null || Number.isNaN(meanVal)) {
        console.log(`${label} Mean: null/NaN`);
        return {ok: false, reason: 'C3'};
      }

      const pct = (100.0 * validCount / totalCount);
      console.log(`${label}: valid=${validCount}/${totalCount} (${pct.toFixed(1)}%), mean=${meanVal.toFixed(3)} nW/cm2/sr`);
      return {ok: true, mean: meanVal, valid: validCount, total: totalCount};
    }

    // 4. Compute stats for both regions
    const aswanStats = await regionStats(aswan, 'Aswan');
    if (!aswanStats.ok) { console.log(aswanStats.reason); return; }

    const gerdStats = await regionStats(gerd, 'GERD');
    if (!gerdStats.ok) { console.log(gerdStats.reason); return; }

    // 5. Validation & Final Answer
    const aswanMean = aswanStats.mean;
    const gerdMean = gerdStats.mean;

    const comparison = aswanMean > gerdMean;
    console.log(`Conclusion: Aswan>GERD = ${comparison}`);

    if (comparison) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (err) {
    console.log(`Error: ${err.message || err}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
